{"content":[{"type":"text","text":"import { Link, useSearchParams } from 'react-router';

import { Button } from '@/components/ui/button';
import { Form, Input } from '@/components/ui/form';
import { paths } from '@/config/paths';
import { useLogin, loginInputSchema } from '@/lib/auth';

type LoginFormProps = {
  onSuccess: () => void;
};

export const LoginForm = ({ onSuccess }: LoginFormProps) => {
  const login = useLogin({
    onSuccess,
  });
  const [searchParams] = useSearchParams();
  const redirectTo = searchParams.get('redirectTo');

  return (
    <div>
      <Form
        onSubmit={(values) => {
          login.mutate(values);
        }}
        schema={loginInputSchema}
      >
        {({ register, formState }) => (
          <>
            <Input
              type="email"
              label="Email Address"
              error={formState.errors['email']}
              registration={register('email')}
            />
            <Input
              type="password"
              label="Password"
              error={formState.errors['password']}
              registration={register('password')}
            />
            <div>
              <Button
                isLoading={login.isPending}
                type="submit"
                className="w-full"
              >
                Log in
              </Button>
            </div>
          </>
        )}
      </Form>
      <div className="mt-2 flex items-center justify-end">
        <div className="text-sm">
          <Link
            to={paths.auth.register.getHref(redirectTo)}
            className="font-medium text-blue-600 hover:text-blue-500"
          >
            Register
          </Link>
        </div>
      </div>
    </div>
  );
};
"}]}

{"content":[{"type":"text","text":"import { useNotifications } from '@/components/ui/notifications';
import { useLogin } from '@/lib/auth';

type UseLoginFormOptions = {
  onSuccess: () => void;
};

export const useLoginForm = ({ onSuccess }: UseLoginFormOptions) => {
  const { addNotification } = useNotifications();
  const login = useLogin({
    onSuccess: () => {
      addNotification({
        type: 'success',
        title: 'Logged in successfully',
      });
      onSuccess();
    },
    onError: (error) => {
      addNotification({
        type: 'error',
        title: 'Failed to log in',
        message:
          error.message || 'An error occurred during login. Please try again.',
      });
    },
  });

  return {
    mutate: login.mutate,
    isPending: login.isPending,
  };
};
"}]}

